package com.rotarypumpers.meraki;
import com.rotarypumpers.meraki.core.BagTracking;import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class BagStore{
 private final File file;BagStore(File files){file=new File(files,"bags-v1.json");}
 static JSONArray validate(JSONArray list)throws Exception{if(list.length()>500)throw new IOException("Maximum 500 bags");JSONArray result=new JSONArray();Set<String> ids=new HashSet<>();for(int i=0;i<list.length();i++){JSONObject b=BagTracking.validate(list.getJSONObject(i));if(!ids.add(b.getString("id")))throw new IOException("Duplicate bag ID");result.put(b);}return result;}
 private static boolean same(JSONObject a,JSONObject b){for(String k:new String[]{"id","name","brand","roast_date","opened_date"})if(!a.optString(k).equals(b.optString(k)))return false;return true;}
 synchronized JSONArray load()throws Exception{if(!file.exists())return new JSONArray();if(file.length()>1024*1024)throw new IOException("Bag library too large");JSONObject root=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));if(!"rp-companion-bags".equals(root.optString("format"))||root.optInt("version")!=1)throw new IOException("Unsupported bag library");return validate(root.getJSONArray("bags"));}
 synchronized JSONObject find(String id)throws Exception{JSONArray list=load();for(int i=0;i<list.length();i++)if(id.equals(list.getJSONObject(i).getString("id")))return list.getJSONObject(i);return null;}
 synchronized void save(JSONArray list)throws Exception{JSONArray clean=validate(list);String text=new JSONObject().put("format","rp-companion-bags").put("version",1).put("bags",clean).toString(2);File tmp=new File(file.getParentFile(),"bags-v1.tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}Files.move(tmp.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
 synchronized void put(JSONObject bag)throws Exception{JSONObject clean=BagTracking.validate(bag);JSONArray list=load(),next=new JSONArray();boolean found=false;for(int i=0;i<list.length();i++){JSONObject b=list.getJSONObject(i);if(b.getString("id").equals(clean.getString("id"))){next.put(clean);found=true;}else next.put(b);}if(!found)next.put(clean);save(next);}
 /** Imported conflicting IDs get a new identity; local bags are never overwritten. */
 synchronized Map<String,String> merge(JSONArray incoming)throws Exception{JSONArray valid=validate(incoming),all=load();Map<String,String> map=new HashMap<>();for(int i=0;i<valid.length();i++){JSONObject b=valid.getJSONObject(i);String old=b.getString("id");JSONObject existing=find(old);if(existing!=null){if(same(existing,b)){map.put(old,old);continue;}b.put("id",UUID.randomUUID().toString());}map.put(old,b.getString("id"));all.put(b);}save(all);return map;}
}
